{{
  // Hoy
  const until = $now.toFormat('yyyy-MM-dd');
  // Hoy menos 2 días (para cubrir un rango de 3 días en total)
  const since = $now.minus({ days: 7 }).toFormat('yyyy-MM-dd');
  // Devuelve el objeto en el formato que la API necesita
  return { since, until };
}}

// --- 1. OBTENER DATOS Y DEFINIR UMBRALES DINÁMICOS ---

// Obtiene los datos del cliente que vienen del nodo anterior.
const datosEntrantes = $('Data entrante').first().json.data;
// Extrae el nombre de la industria. Usa 'Default' si no se encuentra.
const industriaCliente = datosEntrantes.industrias?.nombre || 'Default';

// Objeto de configuración: Aquí vivirán todos tus umbrales.
const umbralesPorIndustria = {
    'Solar': {
        COSTE_POR_ACCION_MAX: 16.00,
        COSTE_POR_ACCION_MIN: 10.00,
        DIAS_MIN_ANTIGUEDAD: 10
    },
    'Default': { // Estos son los umbrales si la industria no coincide con ninguna de las anteriores.
        COSTE_POR_ACCION_MAX: 5.00,
        COSTE_POR_ACCION_MIN: 2.00,
        DIAS_MIN_ANTIGUEDAD: 10
    }
    // Para añadir una nueva industria, simplemente agrega una nueva entrada aquí.
};

// Se seleccionan los umbrales para la industria actual.
const UMBRALES = umbralesPorIndustria[industriaCliente] || umbralesPorIndustria['Default'];

// --- 2. OBTENER DATOS DE LA CUENTA Y EL ESTADO ---
let nombreCliente = "N/A",
    nombreEmpresa = "N/A",
    idCuentaPublicitaria = "N/A",
    esAlertaRepetida = false;

try {
    nombreCliente = datosEntrantes.nombre;
    nombreEmpresa = datosEntrantes.empresa || "No encontrado";
    idCuentaPublicitaria = datosEntrantes["ID-cuenta-publicitaria"] || "No encontrado";
    if (datosEntrantes.status === 'repetido') {
        esAlertaRepetida = true;
    }
} catch (error) {
    // Usar valores por defecto si la data no se encuentra.
}

// --- 3. PROCESAR CAMPAÑAS Y GENERAR TEXTO DE ANÁLISIS ---
let campaigns = [];
try {
  campaigns = $('Aggregate').first().json.data || [];
} catch (e) {
  // campaigns se queda como array vacío.
}

if (campaigns.length === 0) {
    return [{
        json: {
            estado_general: "Sin Campañas Analizables",
            texto_final: null
        }
    }];
}

const alertasDeCampañasTexto = [];

for (const campaign of campaigns) {
    if (!campaign || !campaign.name) continue;

    let estadoFinal, motivoFinal;
    const ahora = new Date($now.toISO());
    const fechaCreacion = new Date(campaign.created_time);
    const fechaLimite = new Date(ahora);
    fechaLimite.setDate(ahora.getDate() - UMBRALES.DIAS_MIN_ANTIGUEDAD);

    if (fechaCreacion >= fechaLimite) {
        estadoFinal = 'Fuera de pool de alertas';
    } else {
        const metrics = campaign.insights?.data[0];
        if (!metrics) {
            estadoFinal = 'REQUIERE REVISIÓN';
            motivoFinal = 'No se encontraron datos de métricas. Posible error de entrega.';
        } else {
            let esCampanaAnalizable = false;
            if (metrics.cost_per_result && metrics.cost_per_result.length > 0) {
                for (const result of metrics.cost_per_result) {
                    const actionType = result.indicator || "";
                    if (actionType.includes('messaging_conversation') || actionType.includes('lead')) {
                        esCampanaAnalizable = true;
                        break;
                    }
                }
            }
            if (!esCampanaAnalizable) {
                estadoFinal = 'No Analizable';
            } else {
                const alertas = [];
                for (const result of metrics.cost_per_result) {
                    if (result.values && result.values.length > 0) {
                        const costValue = parseFloat(result.values[0].value);
                        const actionType = result.indicator || "";
                        const tipo = actionType.includes('lead') ? 'Lead' : 'Conversación';
                        if (actionType.includes('messaging_conversation') || actionType.includes('lead')) {
                            if (costValue > UMBRALES.COSTE_POR_ACCION_MAX) {
                                alertas.push(`Costo por ${tipo} alto ($${costValue.toFixed(2)})`);
                            } else if (costValue < UMBRALES.COSTE_POR_ACCION_MIN) {
                                alertas.push(`Costo por ${tipo} bajo ($${costValue.toFixed(2)})`);
                            }
                        }
                    }
                }
                if (alertas.length > 0) {
                    estadoFinal = 'REQUIERE REVISIÓN';
                    motivoFinal = alertas.join(', ');
                } else {
                    estadoFinal = 'OK';
                }
            }
        }
    }

    if (estadoFinal === 'REQUIERE REVISIÓN') {
        const fechaCreacionObj = new Date(campaign.created_time);
        const opcionesFormato = { day: 'numeric', month: 'short', year: 'numeric' };
        const fechaFormateada = fechaCreacionObj.toLocaleDateString('es-ES', opcionesFormato);

        const textoCampaña = `
-----------------------------------
*Campaña:* ${campaign.name}
*Fecha de creación:* ${fechaFormateada}
*Estado:* ${estadoFinal}
*Razón:* ${motivoFinal}`;
        alertasDeCampañasTexto.push(textoCampaña);
    }
}

// --- 4. ENSAMBLAJE FINAL DEL TEXTO DE ANÁLISIS ---
let estadoGeneral = "Todo OK";
let textoFinal = null;

if (alertasDeCampañasTexto.length > 0) {
    estadoGeneral = "Reporte Existente";
    const titulo = esAlertaRepetida ? "ALERTA REPETIDA" : "ALERTA NUEVA";
    const infoCliente = `*Cliente:* ${nombreCliente}\n*Empresa:* ${nombreEmpresa}\n*ID Cuenta Publicitaria:* ${idCuentaPublicitaria}`;
    textoFinal = `${titulo}\n\n${infoCliente}\n${alertasDeCampañasTexto.join('')}`;
}

// --- 5. OBJETO DE SALIDA ---
return [{
    json: {
        estado_general: estadoGeneral,
        texto_final: textoFinal
    }
}];

